    ll sum = 0;
    if (k == 0) return (ll)n * n;
    int multiplier = 1;
    int i = k + 1; // Initialize outside the loop
    ll total_n = (ll)n; // Store n in a constant

    while (i <= n) {
        if (sum > 1e9) break; // Early termination if sum exceeds threshold
        sum += total_n / i * multiplier; // Use optimized division
        if ((total_n % i) >= k)
            sum += (total_n % i) - k + 1;
        i++;
        multiplier++;
    }
